insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) select id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id from jsonb_to_recordset($bank$[{"id":"che-st-161","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Thermal decomposition $\\mathrm{CaCO_3} \\rightarrow \\mathrm{CaO} + \\mathrm{CO_2}$ is 1 : 1 : 1 in moles. From 1 mol of limestone the carbon dioxide obtained is","options":["0.5 mol","1 mol","2 mol","3 mol"],"answer_index":1,"explanation":"Each mole of $\\mathrm{CaCO_3}$ yields one mole of $\\mathrm{CO_2}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"equation-mole-ratio"},{"id":"che-st-162","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"The laboratory oxygen preparation $2\\mathrm{KClO_3} \\rightarrow 2\\mathrm{KCl} + 3\\mathrm{O_2}$ gives, from 2 mol of chlorate, oxygen amounting to","options":["2 mol","3 mol","4 mol","6 mol"],"answer_index":1,"explanation":"The O$_2$ coefficient is 3 when 2 mol of $\\mathrm{KClO_3}$ decompose.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"equation-mole-ratio"},{"id":"che-st-163","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Complete combustion $\\mathrm{C} + \\mathrm{O_2} \\rightarrow \\mathrm{CO_2}$ links carbon and carbon dioxide in the mole ratio","options":["1 : 1","1 : 2","2 : 1","1 : 4"],"answer_index":0,"explanation":"Coefficients of C and $\\mathrm{CO_2}$ are both 1.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"equation-mole-ratio"},{"id":"che-st-164","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Magnesium burns as $2\\mathrm{Mg} + \\mathrm{O_2} \\rightarrow 2\\mathrm{MgO}$. Oxygen amounting to 1 mol therefore requires magnesium equal to","options":["1 mol","2 mol","0.5 mol","4 mol"],"answer_index":1,"explanation":"Two moles of Mg are needed for each mole of $\\mathrm{O_2}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"equation-mole-ratio"},{"id":"che-st-165","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Methane burns as $\\mathrm{CH_4} + 2\\mathrm{O_2} \\rightarrow \\mathrm{CO_2} + 2\\mathrm{H_2O}$. The oxygen-to-methane mole ratio demanded by the equation is","options":["1 : 1","2 : 1","1 : 2","4 : 1"],"answer_index":1,"explanation":"Two moles of $\\mathrm{O_2}$ are required for every mole of $\\mathrm{CH_4}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"equation-mole-ratio"},{"id":"che-st-166","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Contact-process oxidation $2\\mathrm{SO_2} + \\mathrm{O_2} \\rightarrow 2\\mathrm{SO_3}$ converts 1 mol of oxygen into sulphur trioxide amounting to","options":["1 mol","2 mol","0.5 mol","4 mol"],"answer_index":1,"explanation":"One mole of $\\mathrm{O_2}$ produces two moles of $\\mathrm{SO_3}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"equation-mole-ratio"},{"id":"che-st-167","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Aluminium burns in oxygen: $4\\mathrm{Al} + 3\\mathrm{O_2} \\rightarrow 2\\mathrm{Al_2O_3}$. Four moles of aluminium therefore form alumina equal to","options":["1 mol","2 mol","3 mol","4 mol"],"answer_index":1,"explanation":"The product coefficient is 2 when 4 mol of Al react.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"equation-mole-ratio"},{"id":"che-st-168","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Hydrogen chloride is formed by $\\mathrm{H_2} + \\mathrm{Cl_2} \\rightarrow 2\\mathrm{HCl}$. One mole of hydrogen gas yields HCl equal to","options":["1 mol","2 mol","0.5 mol","4 mol"],"answer_index":1,"explanation":"The HCl coefficient is 2 for each mole of $\\mathrm{H_2}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"equation-mole-ratio"},{"id":"che-st-169","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Propane burns as $\\mathrm{C_3H_8} + 5\\mathrm{O_2} \\rightarrow 3\\mathrm{CO_2} + 4\\mathrm{H_2O}$. Complete combustion of 2 mol of propane releases carbon dioxide amounting to","options":["2 mol","3 mol","6 mol","8 mol"],"answer_index":2,"explanation":"Each mole of $\\mathrm{C_3H_8}$ gives 3 mol $\\mathrm{CO_2}$, so 2 mol give 6 mol.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"equation-mole-ratio"},{"id":"che-st-170","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"A Haber converter is charged with 10 mol of hydrogen and surplus nitrogen. The maximum ammonia that can form is","options":["6.67 mol","10 mol","15 mol","20 mol"],"answer_index":0,"explanation":"From $3\\mathrm{H_2} \\rightarrow 2\\mathrm{NH_3}$, 10 mol H$_2$ produce $(10 \\times 2)/3 = 20/3 \\approx 6.67$ mol NH$_3$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"equation-mole-ratio"},{"id":"che-st-171","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Two moles of $\\mathrm{KClO_3}$ are fully decomposed to KCl and O$_2$. The STP volume of oxygen collected is","options":["22.4 L","44.8 L","67.2 L","89.6 L"],"answer_index":2,"explanation":"2 mol chlorate give 3 mol O$_2$; $3 \\times 22.4 = 67.2$ L at STP.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"equation-mole-ratio"},{"id":"che-st-172","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"A bunsen flame consumes 16 g of methane completely (M = 16 g mol$^{-1}$). The STP volume of $\\mathrm{CO_2}$ produced is","options":["11.2 L","16.0 L","22.4 L","44.8 L"],"answer_index":2,"explanation":"16 g is 1 mol $\\mathrm{CH_4}$ and gives 1 mol $\\mathrm{CO_2}$, which occupies 22.4 L at STP.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"equation-mole-ratio"},{"id":"che-st-173","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"A 50 g charge of $\\mathrm{CaCO_3}$ (M = 100 g mol$^{-1}$) is heated until decomposition is complete. The lime $\\mathrm{CaO}$ (M = 56 g mol$^{-1}$) obtained weighs","options":["28 g","50 g","56 g","44 g"],"answer_index":0,"explanation":"0.50 mol of carbonate yields 0.50 mol of CaO, i.e. 28 g.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"equation-mole-ratio"},{"id":"che-st-174","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Ethane burns as $2\\mathrm{C_2H_6} + 7\\mathrm{O_2} \\rightarrow 4\\mathrm{CO_2} + 6\\mathrm{H_2O}$. A 15 g sample of ethane (M = 30) is burnt in 64 g of oxygen. The mass of $\\mathrm{CO_2}$ formed and the unused $\\mathrm{O_2}$ are","options":["44 g and 8 g","22 g and 16 g","88 g and 0 g","44 g and 0 g"],"answer_index":0,"explanation":"0.50 mol ethane needs 1.75 mol (56 g) O$_2$ and makes 1.0 mol (44 g) CO$_2$; 64 − 56 = 8 g O$_2$ remains.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"equation-mole-ratio"},{"id":"che-st-175","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"After a reaction stops, the starting material that is left unused is called the","options":["limiting reagent","excess reagent","catalyst","theoretical product"],"answer_index":1,"explanation":"The excess reagent remains because the other reactant ran out first.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"limiting-reagent"},{"id":"che-st-176","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"One mole of $\\mathrm{H_2}$ is mixed with one mole of $\\mathrm{O_2}$ and sparked to form water. The reactant that is used up completely is","options":["oxygen","hydrogen","both equally","neither"],"answer_index":1,"explanation":"Water needs H$_2$ : O$_2$ = 2 : 1, so 1 mol H$_2$ is finished while 0.5 mol O$_2$ is still unused.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"limiting-reagent"},{"id":"che-st-177","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"A flask is charged with 1 mol of $\\mathrm{N_2}$ and 1 mol of $\\mathrm{H_2}$ for the Haber reaction. Ammonia production is limited by","options":["nitrogen","hydrogen","both together","the catalyst only"],"answer_index":1,"explanation":"The 1 : 3 nitrogen-to-hydrogen requirement means 1 mol H$_2$ is exhausted long before the nitrogen.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"limiting-reagent"},{"id":"che-st-178","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Two moles of carbon are heated with one mole of oxygen to give only $\\mathrm{CO_2}$. The reagent that decides the amount of $\\mathrm{CO_2}$ is","options":["carbon","oxygen","neither; both finish together","the vessel volume"],"answer_index":1,"explanation":"Each mole of $\\mathrm{CO_2}$ needs 1 mol O$_2$; only 1 mol O$_2$ is supplied, so oxygen limits.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"limiting-reagent"},{"id":"che-st-179","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Equal molar amounts of $\\mathrm{H_2}$ and $\\mathrm{Cl_2}$ are allowed to form HCl. At the end of the reaction","options":["hydrogen remains unused","chlorine remains unused","both gases are completely consumed","no HCl forms"],"answer_index":2,"explanation":"$\\mathrm{H_2} + \\mathrm{Cl_2} \\rightarrow 2\\mathrm{HCl}$ uses the two gases in a 1 : 1 mole ratio.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"limiting-reagent"},{"id":"che-st-180","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Three moles of magnesium ribbon are burnt in one mole of oxygen. Formation of $\\mathrm{MgO}$ is limited by","options":["magnesium","oxygen","both equally","air moisture"],"answer_index":1,"explanation":"$2\\mathrm{Mg} + \\mathrm{O_2}$ needs Mg : O$_2$ = 2 : 1; 1 mol O$_2$ can consume only 2 mol Mg, so oxygen limits.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"limiting-reagent"}]$bank$::jsonb) as t(id text, chapter_id text, subject_id text, stem text, options jsonb, answer_index int, explanation text, images jsonb, source jsonb, difficulty text, concept_id text) on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
insert into question_pyq_meta (question_id, appear_count, years, exams, verified) select question_id, appear_count, years, exams, verified from jsonb_to_recordset($meta$[{"question_id":"che-st-161","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-162","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-163","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-164","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-165","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-166","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-167","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-168","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-169","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-170","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-171","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-172","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-173","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-174","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-175","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-176","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-177","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-178","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-179","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-180","appear_count":0,"years":[],"exams":[],"verified":false}]$meta$::jsonb) as t(question_id text, appear_count int, years int[], exams text[], verified boolean) on conflict (question_id) do update set appear_count = excluded.appear_count, years = excluded.years, exams = excluded.exams, verified = excluded.verified;
